import React from 'react';
import { motion } from 'framer-motion';

const StatsCard = ({ title, value, description, icon, color, theme }) => {
  // Define gradient and glow colors based on the provided color
  const gradients = {
    blue: {
      from: 'from-blue-400',
      to: 'to-blue-600',
      glow: 'rgba(59, 130, 246, 0.3)',
      iconBg: 'bg-blue-500',
      darkIconBg: 'dark:bg-blue-600',
      textColor: 'text-blue-500',
      darkTextColor: 'dark:text-blue-400'
    },
    green: {
      from: 'from-green-400',
      to: 'to-green-600',
      glow: 'rgba(34, 197, 94, 0.3)',
      iconBg: 'bg-green-500',
      darkIconBg: 'dark:bg-green-600',
      textColor: 'text-green-500',
      darkTextColor: 'dark:text-green-400'
    },
    purple: {
      from: 'from-purple-400',
      to: 'to-purple-600',
      glow: 'rgba(168, 85, 247, 0.3)',
      iconBg: 'bg-purple-500',
      darkIconBg: 'dark:bg-purple-600',
      textColor: 'text-purple-500',
      darkTextColor: 'dark:text-purple-400'
    },
    amber: {
      from: 'from-amber-400',
      to: 'to-amber-600',
      glow: 'rgba(251, 191, 36, 0.3)',
      iconBg: 'bg-amber-500',
      darkIconBg: 'dark:bg-amber-600',
      textColor: 'text-amber-500',
      darkTextColor: 'dark:text-amber-400'
    }
  };

  const gradient = gradients[color] || gradients.blue;

  return (
    <motion.div 
      className={`p-6 rounded-2xl backdrop-blur-xl shadow-lg relative overflow-hidden border border-gray-200 dark:border-gray-800 border-opacity-10`}
      whileHover={{ 
        y: -8, 
        boxShadow: `0 20px 25px -5px ${gradient.glow}, 0 8px 10px -6px ${gradient.glow}`,
        transition: { duration: 0.2 } 
      }}
      style={{
        background: 'linear-gradient(135deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.05))'
      }}
    >
      {/* Gradient background effect */}
      <div className={`absolute inset-0 bg-gradient-to-br ${gradient.from}/5 ${gradient.to}/5 opacity-30 z-0`}></div>
      
      {/* Glow effect on hover */}
      <motion.div 
        className={`absolute -inset-0.5 rounded-2xl bg-gradient-to-r ${gradient.from} ${gradient.to} opacity-0 blur-xl z-0`}
        whileHover={{ opacity: 0.15 }}
        transition={{ duration: 0.2 }}
      />
      
      <div className="relative z-10">
        <div className="flex items-center mb-4">
          <div className={`p-3 rounded-xl ${gradient.iconBg} bg-opacity-20 ${gradient.darkIconBg} dark:bg-opacity-30 mr-4 backdrop-blur-lg`}>
            {icon}
          </div>
          <div>
            <h3 className={`text-lg font-semibold ${theme.text.secondary}`}>{title}</h3>
            <p className={`text-2xl font-bold ${gradient.textColor} ${gradient.darkTextColor}`}>
              {value}
            </p>
          </div>
        </div>
        <p className={`text-sm ${theme.text.muted}`}>
          {description}
        </p>
      </div>
    </motion.div>
  );
};

export default StatsCard; 