import React from 'react';
import { motion } from 'framer-motion';
import PremiumCircularProgressBar from './PremiumCircularProgressBar';
import PremiumLineGraph from './PremiumLineGraph';

const StatisticsPanel = ({ 
  completedTasksPercent, 
  taskStatus, 
  studyData, 
  totalStudyHours, 
  theme, 
  itemVariants 
}) => {
  return (
    <div className="grid grid-cols-1 gap-4 mb-6">
      {/* Circular Progress with glass effect */}
      <motion.div 
        className="relative overflow-hidden"
        variants={itemVariants}
        whileHover={{ 
          scale: 1.01,
          transition: { duration: 0.2 } 
        }}
      >
        <div className="absolute inset-0 bg-gradient-to-br from-blue-500/5 to-purple-500/5 rounded-2xl"></div>
        <div className={`p-4 rounded-2xl ${theme.card} backdrop-blur-xl shadow-xl flex flex-col items-center relative z-10 border border-gray-200 dark:border-gray-800 border-opacity-10`}
            style={{
              background: 'linear-gradient(135deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.05))'
            }}
        >
          <h2 className={`text-lg font-semibold mb-4 ${theme.text.primary} bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-indigo-500`}>
            Task Completion
          </h2>
          
          {/* Enhanced progress circle with glow */}
          <div className="relative scale-90">
            <div className="absolute -inset-4 bg-blue-500/10 blur-2xl rounded-full z-0 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
            <PremiumCircularProgressBar 
              progress={completedTasksPercent} 
              status={taskStatus}
              animationDuration={1.2}
              title=""
            />
          </div>
          
          <motion.p 
            className={`mt-2 text-center ${theme.text.secondary} bg-white/5 dark:bg-gray-800/20 px-3 py-1 rounded-lg backdrop-blur-sm text-sm`}
            whileHover={{ y: -2, transition: { duration: 0.2 } }}
          >
            {completedTasksPercent < 30 && "Just getting started. Keep going!"}
            {completedTasksPercent >= 30 && completedTasksPercent < 70 && "Good progress! Keep it up."}
            {completedTasksPercent >= 70 && "Excellent work! Almost done."}
          </motion.p>
        </div>
      </motion.div>
      
      {/* Enhanced Study Time Graph */}
      <motion.div 
        className="relative overflow-hidden"
        variants={itemVariants}
        whileHover={{ 
          scale: 1.01,
          transition: { duration: 0.2 } 
        }}
      >
        <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/5 to-purple-500/5 rounded-2xl"></div>
        <div className={`p-4 rounded-2xl ${theme.card} backdrop-blur-xl shadow-xl relative z-10 border border-gray-200 dark:border-gray-800 border-opacity-10 h-full`}
             style={{
               background: 'linear-gradient(135deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.05))'
             }}
        >
          <div className="flex items-center justify-between mb-4">
            <h2 className={`text-lg font-semibold ${theme.text.primary} bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-purple-500`}>
              Weekly Study
            </h2>
            
            <motion.div
              className="px-2 py-0.5 bg-indigo-500/10 rounded-full text-indigo-500 dark:text-indigo-400 text-xs font-medium"
              whileHover={{ scale: 1.03, transition: { duration: 0.2 } }}
            >
              Last 7 Days
            </motion.div>
          </div>
          
          {/* Graph with enhanced styling for mobile */}
          <div className="relative overflow-x-auto pb-1">
            <div className="absolute inset-0 bg-gradient-to-b from-indigo-500/5 to-transparent rounded-lg"></div>
            <div className="min-w-[280px]">
              <PremiumLineGraph 
                data={studyData}
                width={320}
                height={180}
                color="#818cf8"
                showGlow={true}
                lineWidth={2}
              />
            </div>
          </div>
          
          <div className={`mt-3 flex justify-between ${theme.text.muted} bg-white/5 dark:bg-gray-800/20 px-3 py-2 rounded-lg backdrop-blur-sm text-xs`}>
            <div className="flex flex-col">
              <span className="text-xs text-gray-500 dark:text-gray-400">Total</span>
              <span className="font-medium text-indigo-500 dark:text-indigo-400">{totalStudyHours}h</span>
            </div>
            <div className="flex flex-col">
              <span className="text-xs text-gray-500 dark:text-gray-400">Average</span>
              <span className="font-medium text-purple-500 dark:text-purple-400">{(totalStudyHours / 7).toFixed(1)}h/day</span>
            </div>
            <div className="flex flex-col">
              <span className="text-xs text-gray-500 dark:text-gray-400">Efficiency</span>
              <span className="font-medium text-emerald-500 dark:text-emerald-400">92%</span>
            </div>
          </div>
        </div>
      </motion.div>
    </div>
  );
};

export default StatisticsPanel; 